-- 63 Turning Seasons: one field, four colour grades (`color_lut`), the
-- season turning by fading one out and the next in with PostProcess.set_lut.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/63-turning-seasons.scene"
local SEASONS = { "summer", "autumn", "winter", "dusk" }
local HOLD, FADE = 4.0, 1.2
local captions, turning, grain = true, true, false
local season, t = 1, 0
local status

function init(entity)
    status = Entity.find_by_name("Status")
end

local function lut(i)
    return "luts/" .. SEASONS[i] .. ".png"
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then turning = not turning end
    if Input.is_key_just_pressed("G") then grain = not grain; PostProcess.set_enabled("film_grain", grain) end
    for i = 1, 4 do
        if Input.is_key_just_pressed(tostring(i)) then season = i; t = FADE end
    end
    if turning then t = t + dt end
    -- Fade in over FADE, hold, fade out over FADE, then the next season.
    if t > HOLD + 2 * FADE then
        t = 0
        season = season % #SEASONS + 1
    end
    local strength = math.min(1, t / FADE, (HOLD + 2 * FADE - t) / FADE)
    if not turning then strength = 1 end
    -- Summer is the neutral strip: fading through it is fading through the
    -- field as it is.
    PostProcess.set_lut(lut(season), math.max(0, strength))
    if status then UI.set_text(status, SEASONS[season] .. (grain and "   on film" or "")) end
end
